<template>
  <section ref="workspaceElement" class="exploration-workspace" :class="{'is-resizing':resizing,'chain-collapsed':sidebarCollapsed}" aria-label="AI 数据探索工作空间">
    <header class="exploration-toolbar"><div class="exploration-brand"><strong>Runtime OS</strong><ChevronRight :size="13" /><span>数据探索工作空间</span></div><div class="exploration-toolbar-actions"><button class="exploration-space-switch" type="button" :disabled="busy" aria-label="切换工作空间" @click="showDialog(workspaceDialog)"><span>{{ workspaceBusinessName(space?.title) }}</span><ChevronDown :size="14" /></button><button type="button" :disabled="busy || !space" @click="reload"><RefreshCw :size="14" :class="{'is-spinning':refreshing}" /><span>刷新分析</span></button><button type="button" :disabled="busy || !active?.receipt?.resultAvailable" @click="saveNode"><Save :size="14" /><span>{{ saving?'保存中':'保存节点' }}</span></button></div></header>
    <div v-if="error || notice" class="exploration-feedback" :class="{'has-error':!!error}" :role="error?'alert':'status'">{{ error || notice }}</div>
    <div class="exploration-body" :style="contentStyle">
      <aside v-show="!sidebarCollapsed" class="exploration-chain-pane"><ExplorationChain :nodes="space?.nodes || []" :selected-id="activeId" :collapsed="collapsedBranches" :running-id="runningSpaceId===space?.id?runningId:''" @select="selectNode" @toggle="toggleBranch" @new-root="startRoot" @collapse="sidebarCollapsed=true" /></aside>
      <div v-if="!sidebarCollapsed" class="exploration-divider" role="separator" aria-label="调整思维链宽度" aria-orientation="vertical" :aria-valuenow="sidebarWidth" :aria-valuemin="200" :aria-valuemax="420" tabindex="0" @pointerdown="startResize" @keydown.left.prevent="resizeBy(-16)" @keydown.right.prevent="resizeBy(16)"></div><div v-else class="exploration-divider-placeholder"></div>
      <main class="exploration-main">
        <div class="exploration-scroll-region">
          <div class="exploration-result-heading"><div><button v-if="sidebarCollapsed" type="button" class="exploration-icon-button" aria-label="展开思维链" @click="sidebarCollapsed=false"><PanelLeftOpen :size="18" /></button><h1>{{ space?heading:'开始数据探索' }}</h1></div><div v-if="active?.receipt?.resultAvailable" class="exploration-result-actions"><span v-if="report?.status==='PARTIAL'" class="exploration-partial">数据有限</span><button type="button" class="exploration-text-button" @click="showDialog(detailsDialog)"><Info :size="14" />分析说明</button></div></div>
          <p v-if="summary" class="exploration-summary">{{ summary }}</p>
          <div v-if="loading" class="exploration-loading" role="status"><LoaderCircle :size="20" class="is-spinning" />正在恢复分析…</div>
          <template v-else-if="active?.receipt?.resultAvailable">
            <div v-if="charts.length>1" class="exploration-chart-tabs" role="tablist" aria-label="图形分析"><button v-for="chart in charts" :key="chart.id" type="button" role="tab" :aria-selected="currentChart?.id===chart.id" :title="chartDisplayTitle(chart.title)" :class="{selected:currentChart?.id===chart.id}" @click="selectChart(chart.id)">{{ chartDisplayTitle(chart.title) }}</button></div>
            <section v-if="currentChart" class="exploration-chart-card" aria-label="图形分析"><header><h2>{{ chartDisplayTitle(currentChart.title) }}</h2><div><select v-if="currentChart.kind==='plotly'" :value="effectiveChartType" :disabled="busy || !compatibleTypes.length" aria-label="图表类型" @change="chartType(currentChart,$event)"><option value="">原始图表</option><option v-for="type in chartTypes" :key="type.value" :value="type.value" :disabled="!compatibleTypes.includes(type.value)">{{ type.label }}{{ type.value==='pie'&&!compatibleTypes.includes('pie')?'（需单一非负数列）':'' }}</option></select><button type="button" class="exploration-icon-button" aria-label="放大图表" @click="showDialog(chartDialog)"><Maximize2 :size="16" /></button></div></header><KeepAlive :max="8"><PythonReportChart :key="chartKey" :chart="currentChart" :presentation="active.chartTypes[currentChart.id] || ''" compact @ready="chartReady" /></KeepAlive></section>
            <div v-else class="exploration-empty-result"><Table2 :size="27" /><p>本次分析没有可展示的图表。</p><button type="button" @click="showDialog(detailsDialog)">查看分析结果</button></div>
            <section v-if="chartData" class="exploration-data-preview"><header><button type="button" class="exploration-data-toggle" :aria-expanded="tableOpen" @click="tableOpen=!tableOpen"><ChevronDown v-if="tableOpen" :size="15" /><ChevronRight v-else :size="15" /><Table2 :size="15" />数据预览 <small>{{ chartData.rows.length }} 条</small></button><button v-if="tableOpen" type="button" class="exploration-text-button" @click="showDialog(tableDialog)"><Maximize2 :size="13" />展开查看</button></header><ExplorationDataTable v-if="tableOpen" :key="chartKey" :table="chartData" /></section>
          </template>
          <div v-else-if="active" class="exploration-empty-result"><LoaderCircle v-if="taskRunning && (runningId===active.id || (!!active.agentId && !active.receipt?.terminal))" :size="27" class="is-spinning" /><Table2 v-else :size="27" /><h2>{{ taskRunning && (runningId===active.id || (!!active.agentId && !active.receipt?.terminal))?'正在分析':'这次分析尚未完成' }}</h2><p>你可以先查看其他思维链中的分析结果。</p><button v-if="!analyzing" type="button" :disabled="busy" @click="recover">继续分析</button></div>
          <div v-else class="exploration-empty-result"><Table2 :size="29" /><h2>{{ agentAvailable?'从一个问题开始探索':'选择 Agent，开始图形分析' }}</h2><p>{{ agentAvailable?'描述你关心的问题，Agent 将获取已授权数据并生成分析结果。':'先写下关心的问题，在输入框下方选择 Agent；也可以点击黄色小灯泡获取提问灵感。' }}</p><button v-if="!space" type="button" @click="showDialog(workspaceDialog)">选择工作空间</button></div>
        </div>
        <footer class="exploration-input-region">
          <div v-if="taskRunning || active?.receipt?.resultAvailable" class="exploration-input-context">
            <span v-if="taskRunning"><LoaderCircle :size="12" class="is-spinning" />正在分析<button v-if="runningSpaceId===space?.id && runningId!==activeId" type="button" @click="showRunning">查看当前分析</button></span>
            <span v-else>从“{{ heading }}”继续提问</span>
          </div>
          <PromptComposer v-model="question" compact show-agent-picker agent-required show-idea
            :idea-context="ideaContext" :agents="agents" :agents-loading="agentsLoading || busy"
            :selected-agent-id="selectedAgentId" @update:selected-agent-id="selectAgent"
            :show-suggestions="false" :loading="analyzing"
            :input-disabled="busy || (!!active && !active.receipt?.resultAvailable && !analyzing)"
            :max-length="6000" :workspace-context="workspaceContext" :conversation-key="space?.id || ''"
            :placeholder="active?.receipt?.resultAvailable ? '继续提问或描述想进一步分析的问题……' : '描述你想分析的问题，或点击小灯泡寻找灵感…'" @send="ask" />
        </footer>
      </main>
    </div>
    <Teleport to="body">
      <dialog ref="workspaceDialog" class="exploration-dialog exploration-space-dialog" aria-labelledby="exploration-space-heading" @cancel.prevent="closeDialog(workspaceDialog)"><header><h2 id="exploration-space-heading">工作空间</h2><button type="button" aria-label="关闭工作空间切换" @click="closeDialog(workspaceDialog)"><X :size="18" /></button></header><div class="exploration-space-options"><button v-for="item in spaces" :key="item.id" type="button" :disabled="busy" :class="{selected:space?.id===item.id}" @click="switchSpace(item.id)"><span>{{ workspaceBusinessName(item.title) }}</span><Check v-if="space?.id===item.id" :size="16" /></button></div><form @submit.prevent="create"><h3>新建工作空间</h3><p v-if="hasData">沿用当前分析已授权的数据。</p><input v-model="title" aria-label="工作空间名称" maxlength="120" required /><button type="submit" :disabled="busy"><Plus :size="15" />创建工作空间</button></form></dialog>
      <dialog ref="chartDialog" class="exploration-dialog exploration-expanded-dialog" aria-label="图表放大查看" @cancel.prevent="closeDialog(chartDialog)"><header><h2>{{ chartDisplayTitle(currentChart?.title) }}</h2><button type="button" aria-label="关闭图表放大" @click="closeDialog(chartDialog)"><X :size="19" /></button></header><PythonReportChart v-if="expandedChart && currentChart" :key="chartKey" :chart="currentChart" :presentation="active.chartTypes[currentChart.id] || ''" compact /></dialog>
      <dialog ref="tableDialog" class="exploration-dialog exploration-expanded-dialog" aria-label="数据明细展开查看" @cancel.prevent="closeDialog(tableDialog)"><header><h2>分析数据</h2><button type="button" aria-label="关闭数据展开" @click="closeDialog(tableDialog)"><X :size="19" /></button></header><ExplorationDataTable v-if="chartData" :table="chartData" /></dialog>
      <dialog ref="detailsDialog" class="exploration-dialog exploration-details-dialog" aria-label="分析说明" @cancel.prevent="closeDialog(detailsDialog)"><header><h2>分析说明</h2><button type="button" aria-label="关闭分析说明" @click="closeDialog(detailsDialog)"><X :size="19" /></button></header><div class="exploration-details-body"><p v-if="report?.summary">{{ report.summary }}</p><ul v-if="report?.validation?.warnings?.length"><li v-for="warning in report.validation.warnings" :key="warning">{{ warning }}</li></ul><ReportMarkdown :content="authoredReport" :render-markdown="renderMarkdown" /><details><summary>原始问题</summary><p>{{ active?.question }}</p></details><details><summary>执行凭据</summary><p>{{ active?.receipt?.executionMode }} · {{ active?.receipt?.taskId }}</p><ul><li v-for="reference in active?.receipt?.evidenceRefs || []" :key="reference">{{ reference }}</li></ul></details></div></dialog>
    </Teleport>
  </section>
</template>
<script src="../js/views/DataExplorationView.js"></script>
<style scoped src="../styles/pages/data-exploration.css"></style>
